# Let me try: cell(r,c) is filled if some binary condition on value and position
# For position-based filling, let's check each possible rule

grid_states = {
    7: [[1,0,1],[0,0,0],[1,0,1]],
    6: [[1,1,0],[1,0,1],[0,1,1]],
    4: [[0,0,1],[1,1,0],[1,1,0]],
}

def test_rule(rule_name, condition):
    print(f"\n{rule_name}:")
    for v in [4, 6, 7]:
        match = True
        mismatch = "MISMATCH at"
        for r in range(3):
            for c in range(3):
                expected = grid_states[v][r][c]
                result = condition(v, r, c)
                if expected != result:
                    print(f"  {v} at ({r},{c}): expected {expected}, got {result} -> {mismatch} ({r},{c})")
                    match = False
        if match:
            print(f"  v={v}: ALL MATCH")

# Test various rules
test_rule("v & (r+3*c+6) == v", lambda v, r, c: (v & (r + 3*c + 6)) == v)
test_rule("v % (r+3*c) == 0", lambda v, r, c: v % (r+3*c) == 0 if r+3*c != 0 else True)
test_rule("has_bit_v_with_condition", lambda v, r, c: (v & (1<<(r+c))) != 0 if r+c < 3 else False)
test_rule("v AND (r==c OR r+c==2 OR r*c==0)", lambda v, r, c: (v & 1 if r==c else v & 2 if r+c==2 else v & 4 if r*c==0 else 0) != 0 if r+c < 9 else False)

